import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val n = br.readLine().trim().toLong()
    val x = br.readLine().trim().toInt()

    // We know the final position x after n moves.
    // Moves: odd -> swap(0,1), even -> swap(1,2)
    // We simulate backwards from move n down to 1.
    var pos = x
    var move = n
    while (move > 0) {
        if (move % 2L == 1L) {
            // odd move: swap(0,1)
            pos = when (pos) {
                0 -> 1
                1 -> 0
                else -> 2
            }
        } else {
            // even move: swap(1,2)
            pos = when (pos) {
                1 -> 2
                2 -> 1
                else -> 0
            }
        }
        move--
    }

    println(pos)
}

