import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val n = br.readLine().trim().toLong()
    val x = br.readLine().trim().toInt()

    // Precompute forward mapping for one full cycle of 6 moves
    // forward[initial][moves] = position after 'moves' moves
    val forward = Array(3) { IntArray(6) }
    for (start in 0..2) {
        var pos = start
        for (i in 0 until 6) {
            if ((i + 1) % 2 == 1) { // odd move: swap 0 and 1
                pos = when (pos) {
                    0 -> 1
                    1 -> 0
                    else -> 2
                }
            } else { // even move: swap 1 and 2
                pos = when (pos) {
                    1 -> 2
                    2 -> 1
                    else -> 0
                }
            }
            forward[start][i] = pos
        }
    }

    val movesInCycle = (n % 6).toInt()
    var answer = 0
    for (start in 0..2) {
        val finalPos = if (movesInCycle == 0) start else forward[start][movesInCycle - 1]
        if (finalPos == x) {
            answer = start
            break
        }
    }

    println(answer)
}

